{"packet_id":"D026-01","doc_id":"D026","jurisdiction":"CA","category":"application_screening_fees","lifecycle":"enacted","title":"California application screening fee cap","requirement":"A landlord or agent may charge an applicant an application screening fee only when a rental unit is or will be available, may not exceed $30 per applicant (CPI-adjusted annually), and must provide an itemized receipt, refund unused amounts, and deliver the credit report within seven days.","key_value":"$30 per applicant, CPI-adjusted annually","coverage_conditions":"Applies to any landlord (owner of residential rental property) or agent and any applicant, including a guarantor or cosigner, requesting to rent a residential unit.","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":"No refund is required for an applicant denied after consideration for failing the landlord's established screening criteria.","penalty":null,"effective_date":"2026-01-01","valid_through":null,"citation":"Cal. Civ. Code § 1950.6","quoted_span":"In no case shall the amount of the application screening fee charged by the landlord or their agent be greater than thirty dollars ($30) per applicant.","interaction":"Does not preempt federal or state housing assistance program rules on collection of deposits and fees.","relations":[],"confidence":0.95,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D026-01","doc_id":"D026","jurisdiction":"CA","category":"screening_restrictions","lifecycle":"enacted","title":"California application screening order and criteria rule","requirement":"A landlord charging a screening fee must consider completed applications in the order received, give screening criteria in writing with the application, approve the first applicant who meets the criteria, and charge no fee unless the application is actually considered.","key_value":null,"coverage_conditions":"Applies to any landlord (owner of residential rental property) or agent and any applicant requesting to rent a residential unit.","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":"2026-01-01","valid_through":null,"citation":"Cal. Civ. Code § 1950.6","quoted_span":"Completed applications are considered, as provided for in the landlord’s established screening criteria, in the order in which the completed applications were received.","interaction":null,"relations":[],"confidence":0.9,"conflict_flag":false,"conflict_note":null}
